B 11/11
我生日哎。
数位最多两位，这个数位分解很简单。这里有一种简单粗暴的办法：如果十位是 0 就让它等于个位就好了，反正不影响结果。
ACCode：
#include &lt;bits/stdc++.h&gt;using namespace std;const int N = 110;int n, d[N], ans;int main() {	scanf("%d", &amp;n);	for (int i = 1;i &lt;= n;i++) {		scanf("%d", &amp;d[i]);		for (int j = 1;j &lt;= d[i];j++) {			int ge = j % 10, shi = j / 10, gei = i % 10, shii = i /10;			if (shi == 0)				shi = ge;			if (shii == 0)				shii = gei;			if (ge == shi &amp;&amp; shi == gei &amp;&amp; gei == shii)				ans++;		}	}	printf("%d\n", ans);	return 0;}

