C Consecutive


    Tips：区间求答案，就想前缀和。



如果相等，就在答案数组上 + 1，否则就不加
ACCode with 注释：
#include &lt;bits/stdc++.h&gt;using namespace std;const int N = 3e5 + 10;int n, q, l, r, cnt[N];string s;int main() {    scanf("%d%d", &amp;n, &amp;q);    cin &gt;&gt; s;    s = ' ' + s;  // 前缀和从1开始    for (int i = 1;i &lt;= n;i++)        if (s[i] == s[i + 1])  // 相等            cnt[i] = cnt[i - 1] + 1;  // 记录        else            cnt[i] = cnt[i - 1];    for (int i = 1;i &lt;= q;i++) {        scanf("%d%d", &amp;l, &amp;r);        printf("%d\n",  cnt[r - 1] - cnt[l - 1]);        /*因为上面是s[i + 1]与s[i]相同就记录了，        所以要用cnt[r - 1]以防在最后一组相同的区间内只有其中一个字符，        即避免如aabb中的bb在筛查1~3的时候被计算*/    }    return 0;}

