考虑到老师不能砍树，所以最少补种树就是把剩下那二位的种树数补成最多的那位。
这里介绍个小语法：
max({a, b, c});max(max(a, b), c);

两行代码都是在求 
的最大值，但是第二个是两两求，第一个是整体求，稍微方便一点。

ACCode：
/*Code by Leo2011*/#include &lt;bits/stdc++.h&gt;#define log printf#define EPS 1e-8#define INF 0x3f3f3f3f#define FOR(i, l, r) for (int(i) = (l); (i) &lt;= (r); ++(i))#define IOS                      \	ios::sync_with_stdio(false); \	cin.tie(nullptr);            \	cout.tie(nullptr);using namespace std;typedef __int128 i128;typedef long long ll;typedef pair&lt;int, int&gt; PII;int a, b, c;template &lt;typename T&gt;inline T read() {	T sum = 0, fl = 1;	char ch = getchar();	for (; !isdigit(ch); ch = getchar())		if (ch == '-') fl = -1;	for (; isdigit(ch); ch = getchar()) sum = sum * 10 + ch - '0';	return sum * fl;}template &lt;typename T&gt;inline void write(T x) {	if (x &lt; 0) {		putchar('-'), write&lt;T&gt;(-x);		return;	}	static T sta[35];	int top = 0;	do { sta[top++] = x % 10, x /= 10; } while (x);	while (top) putchar(sta[--top] + 48);}int main() {	a = read&lt;int&gt;(), b = read&lt;int&gt;(), c = read&lt;int&gt;();	write&lt;int&gt;(3 * max({a, b, c}) - (a + b + c));	return 0;}

